/* main.c: RP2040 trigger box (Raspberry Pi Pico), generated by Vantage for @@PROJECT@@ · @@VARIANT@@.
 *
 * PIO0 SM0 (tb_trigger) drives the trigger lines on GP@@BASE_PIN@@..GP@@LAST_PIN@@ from a queue of edges the CPU
 * computes with the scheduling core (trigger_core.c); PIO0 SM1 (tb_capture) timestamps the GNSS PPS on
 * GP@@PPS_PIN@@ to the cycle. The core disciplines the schedule to the PPS (see trigger_core.h); without PPS it runs
 * on the board's crystal (free, or holdover with the learned frequency).
 *
 * Self-test: hold GP@@SELFTEST_PIN@@ low at power-up: line n then gives n + 1 pulses of 2 ms, 20 ms apart, every second
 * (100 ms after the PPS), so a scope or an LED shows which line is wired where.
 *
 * Status: one line a second on the USB serial port (115200 8N1 on any terminal); the LED is on when locked, blinks
 * once a second while free or locking and four times a second in holdover.
 *
 * Only trigger pulses come out of this board. It drives nothing else.
 */
#include <stdio.h>

#include "hardware/clocks.h"
#include "hardware/gpio.h"
#include "hardware/pio.h"
#include "hardware/watchdog.h"
#include "pico/stdlib.h"

#include "trigger.pio.h"
#include "trigger_core.h"
#include "trigger_plan.h"
#include "tb_rp2040.h"

#define SM_TRIG 0
#define SM_CAP 1
#define CYCLES_PER_US (TB_HZ / 1000000)

static tb_state_t st;
static tb_rp_cap_t cap;
static uint64_t t0_us;
static int64_t last_edge;
static uint32_t underruns;
static uint off_trig, off_cap;

static int64_t now_cycles(void)
{
    return (int64_t)(time_us_64() - t0_us) * CYCLES_PER_US;
}

static void queue_edges(int first)
{
    /* two words per edge; keep the joined 8-word FIFO topped up so the state machine never waits */
    while (pio_sm_get_tx_fifo_level(pio0, SM_TRIG) <= 6) {
        int64_t e;
        uint32_t state;
        tb_next_edge(&st, &e, &state);
        pio_sm_put(pio0, SM_TRIG, first ? tb_rp_first_word(e) : tb_rp_word(last_edge, e));
        pio_sm_put(pio0, SM_TRIG, state ^ TB_OUT_INVERT);
        last_edge = e > last_edge + 3 || first ? e : last_edge + 3;
        first = 0;
    }
}

static void start(const tb_plan_t *plan)
{
    pio_set_sm_mask_enabled(pio0, (1u << SM_TRIG) | (1u << SM_CAP), false);
    pio_sm_clear_fifos(pio0, SM_TRIG);
    pio_sm_clear_fifos(pio0, SM_CAP);
    pio_sm_restart(pio0, SM_TRIG);
    pio_sm_restart(pio0, SM_CAP);
    pio_sm_exec(pio0, SM_TRIG, pio_encode_jmp(off_trig));      /* both programs from their first instruction */
    pio_sm_exec(pio0, SM_CAP, pio_encode_jmp(off_cap));
    pio_sm_exec(pio0, SM_CAP, pio_encode_mov_not(pio_x, pio_null));
    pio_sm_set_pins_with_mask(pio0, SM_TRIG, (uint32_t)TB_OUT_INVERT << TB_BASE_PIN,
                              ((1u << TB_N_LINES) - 1u) << TB_BASE_PIN);       /* every line idle */
    tb_init(&st, plan, 0);
    cap.k = 0;
    last_edge = 0;
    queue_edges(1);
    t0_us = time_us_64();
    pio_enable_sm_mask_in_sync(pio0, (1u << SM_TRIG) | (1u << SM_CAP));
}

int main(void)
{
    const tb_plan_t *plan = &TB_PLAN;
    uint64_t next_status = 0;

    set_sys_clock_khz(TB_HZ / 1000, true);
    stdio_init_all();
    gpio_init(TB_SELFTEST_PIN);
    gpio_set_dir(TB_SELFTEST_PIN, GPIO_IN);
    gpio_pull_up(TB_SELFTEST_PIN);
    gpio_init(TB_LED_PIN);
    gpio_set_dir(TB_LED_PIN, GPIO_OUT);
    sleep_ms(5);
    if (!gpio_get(TB_SELFTEST_PIN))
        plan = &TB_PLAN_SELFTEST;

    off_trig = pio_add_program(pio0, &tb_trigger_program);
    off_cap = pio_add_program(pio0, &tb_capture_program);
    tb_trigger_program_init(pio0, SM_TRIG, off_trig, TB_BASE_PIN, TB_N_LINES);
    tb_capture_program_init(pio0, SM_CAP, off_cap, TB_PPS_PIN);
    start(plan);
    watchdog_enable(500, 1);

    for (;;) {
        int64_t now;
        watchdog_update();
        /* PPS captures first: the edges queued next use the newest anchor */
        while (!pio_sm_is_rx_fifo_empty(pio0, SM_CAP)) {
            uint32_t x = pio_sm_get(pio0, SM_CAP);
            tb_on_pps(&st, tb_rp_capture(&cap, x, now_cycles()));
        }
        now = now_cycles();
        tb_poll(&st, now);
        if (pio0->fdebug & (1u << (PIO_FDEBUG_TXSTALL_LSB + SM_TRIG))) {
            /* the queue ran dry, so the state machine's timeline slipped: start again (the lines go idle first) */
            pio0->fdebug = 1u << (PIO_FDEBUG_TXSTALL_LSB + SM_TRIG);
            underruns++;
            start(plan);
            continue;
        }
        queue_edges(0);
        if (time_us_64() >= next_status) {
            next_status = time_us_64() + 1000000;
            printf("%s plan=%s pps=%lu missed=%lu steps=%lu outliers=%lu resid_ns=%ld ppb=%ld underruns=%lu\n",
                   tb_state_name(st.state), plan == &TB_PLAN ? "normal" : "selftest", (unsigned long)st.pps,
                   (unsigned long)st.missed, (unsigned long)st.steps, (unsigned long)st.outliers,
                   (long)(st.resid * 1000000000 / TB_HZ), (long)tb_ppb(&st), (unsigned long)underruns);
        }
        {
            uint64_t ms = time_us_64() / 1000;
            int on = st.state == TB_LOCKED ? 1 : st.state == TB_HOLDOVER ? (ms / 125) % 2 : (ms / 500) % 2;
            gpio_put(TB_LED_PIN, on);
        }
    }
}
